import { MakeLogicType, actions, connect, kea, key, listeners, path, props, reducers, selectors } from 'kea'
import posthog from 'posthog-js'

import { playerSidebarLogic } from 'scenes/session-recordings/player/sidebar/playerSidebarLogic'

import { SessionRecordingSidebarTab } from '~/types'

export type ReplayListSegment = 'picks' | 'recordings' | 'moments'

export interface ReplayListColumnLogicProps {
    logicKey: string
}

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface replayListColumnLogicValues {
    effectiveSegmentFor: (picksMode: 'picks' | 'recordings' | null, momentsAvailable: boolean) => ReplayListSegment
    segment: ReplayListSegment | null
}

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface replayListColumnLogicActions {
    setSidebarTab: (tab: SessionRecordingSidebarTab) => {
        tab: SessionRecordingSidebarTab
    } // playerSidebarLogic
    setSegment: (segment: ReplayListSegment) => {
        segment: ReplayListSegment
    }
}

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface replayListColumnLogicMeta {
    key: string
    __keaTypeGenInternalSelectorTypes: {
        effectiveSegmentFor: (
            segment: ReplayListSegment | null
        ) => (picksMode: 'picks' | 'recordings' | null, momentsAvailable: boolean) => ReplayListSegment
    }
}

export type replayListColumnLogicType = MakeLogicType<
    replayListColumnLogicValues,
    replayListColumnLogicActions,
    ReplayListColumnLogicProps,
    replayListColumnLogicMeta
>

/** Which segment the watch-layout list column shows: What to watch, All recordings, or the open recording's Moments. */
export const replayListColumnLogic = kea<replayListColumnLogicType>([
    path((key) => ['scenes', 'session-recordings', 'playlist', 'replayListColumnLogic', key]),
    props({} as ReplayListColumnLogicProps),
    key((props) => props.logicKey),
    connect(() => ({
        actions: [playerSidebarLogic, ['setTab as setSidebarTab']],
    })),
    actions({
        setSegment: (segment: ReplayListSegment) => ({ segment }),
    }),
    reducers({
        // Null until the viewer picks one, so the picks logic keeps deciding where a fresh page lands.
        segment: [null as ReplayListSegment | null, { setSegment: (_, { segment }) => segment }],
    }),
    selectors({
        effectiveSegmentFor: [
            (s) => [s.segment],
            (segment: ReplayListSegment | null) =>
                (picksMode: 'picks' | 'recordings' | null, momentsAvailable: boolean): ReplayListSegment => {
                    const chosen = segment ?? picksMode ?? 'recordings'
                    if (chosen === 'picks' && picksMode === null) {
                        return 'recordings'
                    }
                    if (chosen === 'moments' && !momentsAvailable) {
                        return 'recordings'
                    }
                    return chosen
                },
        ],
    }),
    listeners(({ actions }) => ({
        setSegment: ({ segment }) => {
            posthog.capture('session recording list segment changed', { segment })
        },
        // Summarize and View details still ask for the Observations tab; in this layout that content is the Moments segment.
        setSidebarTab: ({ tab }) => {
            if (tab === SessionRecordingSidebarTab.OBSERVATIONS) {
                actions.setSegment('moments')
            }
        },
    })),
])
